const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

const receipt_row = require('receipt_row')
const send_button = require('button')
const send_invoice_modal = require('send_invoice_modal')

module.exports = create_invoice_confirmation

async function create_invoice_confirmation(opts = {}, { onClose, contacts = [] } = {}) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = { style: inject, data: ondata, icons: iconject }

  let dricons = []
  let modalMounted = false
  let current_contacts = Array.isArray(contacts) ? contacts : []
  const receipt_rows = []

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="invoice-card">
      <div class="invoice-header">
        <div class="title-container">
          <div class="invoice-title">Create Lightning Invoice</div>
          <div class="light-icon-small"></div>
        </div>
        <div class="close-icon"></div>
      </div>
      <div class="bolt11-display" style="display:none; margin: 12px 0; padding: 12px; background: #0d1117; border-radius: 10px; border: 1px solid #30363d;">
        <div style="font-size: 0.75em; color: #8b949e; margin-bottom: 6px; text-transform: uppercase; letter-spacing: 0.05em;">⚡ Lightning Invoice (bolt11)</div>
        <div class="bolt11-string" style="font-family: monospace; font-size: 0.72em; color: #58a6ff; word-break: break-all; line-height: 1.5; margin-bottom: 10px;"></div>
        <button class="copy-bolt11-btn" style="width: 100%; padding: 9px; background: linear-gradient(135deg, #f59e0b, #f97316); color: #fff; border: none; border-radius: 8px; font-weight: 600; font-size: 0.85em; cursor: pointer; letter-spacing: 0.03em;">📋 Copy Invoice</button>
      </div>
      <div class="receipt-rows"></div>
      <div class="send-button"></div>
      <div class="share-confirmation hidden" role="dialog" aria-modal="true" aria-labelledby="share-confirmation-title">
        <div class="share-confirmation-card">
          <div class="share-confirmation-title" id="share-confirmation-title">Share invoice?</div>
          <div class="share-confirmation-message">Do you want to share this Lightning invoice with a contact?</div>
          <div class="share-confirmation-actions">
            <button class="share-cancel-btn" type="button">No</button>
            <button class="share-continue-btn" type="button">Yes, share</button>
          </div>
        </div>
      </div>
      <div class="send-modal-container hidden"></div>
      <style></style>
    </div>
  `

  const style = shadow.querySelector('style')
  const rows_el = shadow.querySelector('.receipt-rows')
  const send_button_container = shadow.querySelector('.send-button')
  const close_icon = shadow.querySelector('.close-icon')
  const modal_container = shadow.querySelector('.send-modal-container')
  const bolt11_display = shadow.querySelector('.bolt11-display')
  const bolt11_string_el = shadow.querySelector('.bolt11-string')
  const copy_btn = shadow.querySelector('.copy-bolt11-btn')
  const invoice_title = shadow.querySelector('.invoice-title')
  const share_confirmation = shadow.querySelector('.share-confirmation')
  const share_cancel_btn = shadow.querySelector('.share-cancel-btn')
  const share_continue_btn = shadow.querySelector('.share-continue-btn')

  // Close the invoice card
  close_icon.addEventListener('click', () => {
    if (onClose) onClose()
  })

  const subs = await sdb.watch(onbatch)

  // Render send button (subs[0])
  const button_component = await send_button(subs[0])
  send_button_container.append(button_component)

  button_component.addEventListener('click', () => {
    share_confirmation.classList.remove('hidden')
    share_confirmation.style.display = 'flex'
    share_continue_btn.focus()
  })

  share_cancel_btn.addEventListener('click', () => {
    share_confirmation.classList.add('hidden')
    share_confirmation.style.display = 'none'
    modal_container.classList.add('hidden')
    invoice_title.textContent = 'Invoice Created'
  })

  share_confirmation.addEventListener('click', event => {
    if (event.target === share_confirmation) {
      share_confirmation.classList.add('hidden')
      share_confirmation.style.display = 'none'
    }
  })

  // Render send_invoice_modal only after sharing is confirmed (subs[1])
  share_continue_btn.addEventListener('click', async () => {
    share_confirmation.classList.add('hidden')
    share_confirmation.style.display = 'none'
    if (!modalMounted) {
      const modal_component = await send_invoice_modal(subs[1], {
        onClose: () => modal_container.classList.add('hidden'),
        contacts: current_contacts
      })
      modal_container.append(modal_component)
      modalMounted = true
    } else {
      const modal_component = modal_container.firstElementChild
      if (modal_component && typeof modal_component.updateContacts === 'function') {
        modal_component.updateContacts(current_contacts)
      }
    }
    modal_container.classList.remove('hidden')
  })

  for (let i = 2; i < subs.length; i++) {
    const row_component = await receipt_row(subs[i])
    receipt_rows.push(row_component)
    rows_el.append(row_component)
  }

  // Called by parent (lightning_buttons) when the backend returns a generated invoice
  el.updateInvoiceData = function (data) {
    if (!data) return
    const bolt11 = data.bolt11 || data.invoice || ''
    if (!bolt11) return

    bolt11_string_el.textContent = bolt11
    bolt11_display.style.display = 'block'
    invoice_title.textContent = 'Invoice Created'

    const amount = Number(data.amount_btc)
    const formattedAmount = Number.isFinite(amount)
      ? amount.toFixed(8).replace(/0+$/, '').replace(/\.$/, '')
      : '0'

    if (receipt_rows[0] && typeof receipt_rows[0]._update === 'function') {
      receipt_rows[0]._update({
        label: 'Note',
        value: data.description || ''
      })
    }

    if (receipt_rows[1] && typeof receipt_rows[1]._update === 'function') {
      receipt_rows[1]._update({
        label: 'Amount',
        value: `${formattedAmount} BTC`,
        icon: 'lightning.svg',
        convert: true
      })
    }

    copy_btn.onclick = function () {
      if (navigator.clipboard) {
        navigator.clipboard.writeText(bolt11).then(() => {
          const orig = copy_btn.textContent
          copy_btn.textContent = '✅ Copied!'
          setTimeout(() => { copy_btn.textContent = orig }, 1500)
        }).catch(() => { })
      }
    }
  }

  el.updateContacts = function (nextContacts) {
    current_contacts = Array.isArray(nextContacts) ? nextContacts : []
    const modal_component = modal_container.firstElementChild
    if (modal_component && typeof modal_component.updateContacts === 'function') {
      modal_component.updateContacts(current_contacts)
    }
  }

  return el

  function fail(data, type) {
    throw new Error('invalid message', { cause: { data, type } })
  }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(p => drive.get(p).then(f => f.raw)))
      const fn = on[type] || fail
      await fn(data, type)
    }
  }

  function inject(data) {
    style.textContent = data[0]
  }

  function iconject(data) {
    dricons = data
    const light_icon = shadow.querySelectorAll('.light-icon-small')
    const close_icon = shadow.querySelector('.close-icon')
    light_icon.forEach(el => el.innerHTML = dricons[0])
    close_icon.innerHTML = dricons[1]
  }

  async function ondata(data) { }
}

function fallback_module() {
  return {
    api,
    _: {
      'button': { $: '' },
      'send_invoice_modal': { $: '' },
      'receipt_row': { $: '' },
    }
  }

  function api(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}

    const button = { mapping: { style: 'style', data: 'data', icons: 'icons' }, 0: { label: 'Send' } }
    const send_invoice_modal = {
      mapping: { style: 'style', data: 'data', icons: 'icons' }, 1: { value: [] }
    }

    const receipt_row = { mapping: { style: 'style', data: 'data', icons: 'icons' } }

    opts.value.slice(1).forEach((row, i) => {
      receipt_row[i + 2] = row
    })

    return {
      drive: {
        'icons/': { 'lightning.svg': { '$ref': 'lightning.svg' }, 'x.svg': { '$ref': 'x.svg' } },
        'style/': { 'create_invoice_confirmation.css': { '$ref': 'create_invoice_confirmation.css' } },
        'data/': { 'opts.json': { raw: opts || {} } }
      },
      _: { button, send_invoice_modal, receipt_row }
    }
  }
}
